"""Fail closed for prototype recipes that cannot support a real evaluation.

Public measurements do not turn invented features or rule-generated targets
into observed ground truth. These recipes must be replaced by audited public
source adapters before training is enabled again; augmentation is permitted
only within each training fold after splitting by participant/route.
"""

REJECTED_RECIPES = {
    "fatigue": "PAMAP2 speed is assigned by activity; heart-rate reserve uses assumed baselines; fatigue targets are generated by project rules, not observed fatigue labels.",
    "physio_risk": "BIDMC speed and elevation are randomly generated; fatigue and risk targets are generated by project rules, not observed trekking outcomes.",
    "route_difficulty": "Route targets and fallback technical scores are generated from the same slope/exertion features instead of independently published difficulty ratings.",
}


def require_public_ground_truth(recipe: str) -> None:
    """Reject legacy recipes and unknown recipes; there is no opt-out flag."""
    reason = REJECTED_RECIPES.get(recipe, "No audited public-source adapter is registered.")
    raise ValueError(
        f"Real evaluation unavailable for {recipe}: {reason} "
        "Replace the legacy recipe with an audited adapter preserving public "
        "measurements, independent labels, source provenance and evaluation groups. "
        "No training/model export was performed."
    )
